import{U as g,u,k as d,aR as l,I as y,aS as b,g as h,O as f,aP as w,aT as v}from"./D6nN6vch.js";function j(a=!1){const t=g,e=t.l.u;if(!e)return;let n=()=>f(t.s);if(a){let s=0,o={};const m=w(()=>{let c=!1;const r=t.s;for(const i in r)r[i]!==o[i]&&(o[i]=r[i],c=!0);return c&&s++,s});n=()=>h(m)}e.b.length&&u(()=>{p(t,n),l(e.b)}),d(()=>{const s=y(()=>e.m.map(b));return()=>{for(const o of s)typeof o=="function"&&o()}}),e.a.length&&d(()=>{p(t,n),l(e.a)})}function p(a,t){if(a.l.s)for(const e of a.l.s)h(e);t()}v();const k=1,A={name:"Andrea Lissak",wordmark:"andrea",role:"Software Engineer",tagline:"I build software across web, mobile, backend, computer vision and hardware.",quote:"I like working with people on small, useful tools that stay useful. Paid cloud infrastructure isn’t always necessary and there are often overlooked ways to run an app at zero cost. Where I can, I build for the browser and use free services for storage, keeping maintenance low so projects can survive beyond the initial enthusiasm.",projectHandover:"When you commission a project, you get full ownership of the finished product, with a clean handover once the work is complete. You can come back for improvements, further iterations or fixes. I’m not currently offering ongoing project management.",pageTitle:"Andrea Lissak — Software Engineer",description:"Andrea Lissak's portfolio: substantial apps and web tools, work at Yahoo, and a wider collection of smaller experiments across web, mobile, backend, computer vision and hardware.",featuredHeading:"Featured Projects",workHeading:"Work",archiveHeading:"More Projects",contactHeading:"Send a message",contactCopy:"Send me a message directly — no account needed. Leave your email or a handle on your preferred messaging platform.",messageLabel:"Your message",messagePlaceholder:"Tell me what you have in mind, and how to reach you (email, phone, or another way)…",sendLabel:"Send message",sentMessage:"Thanks — your message was sent.",emailIntro:"Prefer email? Write directly to",email:"andrea.media.info@gmail.com",githubUrl:"https://github.com/yissok",accessSentMessage:"Thanks — your request was sent.",detailHeading:"What it does",notesHeading:"Implementation notes",missingHeading:"Nothing here",missingCopy:"That page does not exist.",noScriptIntro:"Enable JavaScript to explore the project previews. You can also browse"},S=[{id:"penguin-steps",name:"Penguin Steps",category:"iOS · Walking with a partner",kind:"app",color:"#c9ddd8",accent:"#356d62",image:"penguin-steps-screen.jpg",media:[{type:"image",src:"penguin-steps-screen.jpg",alt:"Penguin Steps main screen",poster:""},{type:"image",src:"penguinsteps2.jpg",alt:"Penguin Steps second screen",poster:""}],description:"Compare your daily steps with a partner through Apple Health. Your penguins move as you walk, turning the day into a shared race.",tags:["Apple Health","Swift","Firebase"],note:"Pairing and step tracking run through the native iOS app.",links:[["App Store","https://apps.apple.com/gb/app/penguin-steps/id6762652426"]],private:!0},{id:"dropleet",name:"Dropleet",category:"Web · Java interview practice",kind:"web",color:"#e8d6cc",accent:"#a44b32",image:"dropleet.jpg",media:[{type:"image",src:"dropleet.jpg",alt:"Dropleet main screen",poster:""},{type:"image",src:"drop2.png",alt:"Dropleet second screen",poster:""},{type:"image",src:"drop3.png",alt:"Dropleet third screen",poster:""}],description:"Breaks LeetCode problems into bite-sized reasoning steps you can work through interactively. Question sets are LLM-generated from user-supplied JSON, answers flow through Google Forms, and the whole thing runs as a static site you can share — no account or backend required.",tags:["Java","Algorithms","LLM-generated"],note:"",links:[["Visit site","https://dropleet.co.uk/"]],private:!0},{id:"reacter",name:"Reacter",category:"iOS · Reaction game",kind:"app",color:"#e5d0cc",accent:"#a63d3d",image:"reacter-screen.jpg",media:[{type:"image",src:"reacter-screen.jpg",alt:"Reacter interface preview",poster:""},{type:"video",src:"demos/reacter.mp4",alt:"Reacter demo",poster:"demos/reacter.png",original:"https://yissok.github.io/HQ_videos/reacter.mp4"}],description:"A tap-based reaction game for iPhone and iPad. First released in 2015.",tags:["Native iOS","Swift"],note:"",links:[["App Store","https://apps.apple.com/gb/app/reacter/id993435226"]]},{id:"pixelbot",name:"Pixelbot",category:"iOS + macOS · Pixel monitoring",kind:"app",color:"#d5d7e7",accent:"#545b8e",image:"pixelbot-screen.jpg",media:[{type:"video",src:"pixelbot-video.mp4",alt:"Pixelbot demo",poster:""},{type:"image",src:"pixelbot-screen.jpg",alt:"Pixelbot iPhone app",poster:""},{type:"image",src:"pixelbot-dashboard-screen.jpg",alt:"Pixelbot Mac dashboard",poster:""}],description:"Watch a pixel on your Mac and get a notification on your phone when it changes — useful for queues, long operations and finished downloads.",tags:["macOS app","iOS app","No account"],note:"The Mac app watches the pixel; the iOS app delivers the notification. No account required.",links:[["App Store","https://apps.apple.com/gb/app/pixelbot/id1560553386"],["Mac App Store","https://apps.apple.com/gb/app/pixelbot-dashboard/id1560523831?mt=12"]],private:!0},{id:"cell",name:"Cell Counter",category:"Web · Cell counting",kind:"web",color:"#ddd5e3",accent:"#76518b",image:"cell.jpg",media:[{type:"image",src:"cell1.png",alt:"Cell Counter main screen",poster:""},{type:"image",src:"cell2.png",alt:"Cell Counter second screen",poster:""},{type:"image",src:"cell3.png",alt:"Cell Counter third screen",poster:""},{type:"image",src:"cell4.png",alt:"Cell Counter fourth screen",poster:""}],description:"Counts the cells visible in a photo of a microscope screen, plus tools for seeding density, well counts and media volumes. No account required.",tags:["Computer vision","Image processing","No account"],note:"",links:[["Visit site","https://scout-38aa2.web.app/cell"]],private:!0},{id:"latent-semantic-analysis",name:"Latent Semantic Analysis",category:"Web · Keyword mind maps",kind:"web",color:"#d7dfca",accent:"#657948",image:"project-placeholder.svg",media:[{type:"video",src:"demos/yoogle.mp4",alt:"Latent Semantic Analysis demo",poster:"demos/yoogle.png",original:"https://yissok.github.io/HQ_videos/yoogle.mp4"},{type:"image",src:"uploads/091577dd-26ab-4edb-bbb7-ffc92e782451-screenshot-2026-09-23-190226.png",alt:"",poster:""},{type:"image",src:"uploads/1f9ebed1-fbae-4aa7-8e0c-14611d1944a4-screenshot-2026-09-23-190232.png",alt:"",poster:""}],description:"Give it a set of keywords and it estimates how strongly each pair relates using Google search signals, then draws a weighted graph.",tags:["JS","SQL","PHP"],note:"",links:[["View repository","https://github.com/yissok/Blending-Google-and-the-old-Yahoo"]],placeholder:!0},{id:"gym-app",name:"Gym Crowdedness",category:"Arduino · Hardware + backend",kind:"web",color:"#e5dfca",accent:"#827034",image:"project-placeholder.svg",media:[{type:"image",src:"uploads/5618a841-5a7e-4881-9dae-5a9c05f97586-screenshot-2026-09-21-180802.png",alt:"",poster:""},{type:"image",src:"uploads/5a2e6522-8749-46a1-86bd-e6bbb1864992-screenshot-2026-09-21-180820.png",alt:"",poster:""},{type:"video",src:"demos/fitin.mp4",alt:"Gym Crowdedness demo",poster:"demos/fitin.png",original:"https://yissok.github.io/HQ_videos/fitin.mp4"},{type:"image",src:"uploads/75a31333-808c-49d1-811a-4ca113081b41-screenshot-2026-09-21-180725.png",alt:"",poster:""}],description:"Tracks how crowded a gym is using Arduino-based sensing, with devices reporting to a backend over HTTP.",tags:["Arduino","Hardware","Backend"],note:"",links:[["View repository","https://github.com/yissok/Gym-App"]],placeholder:!0},{id:"family",name:"Family Tree",category:"Web · Family tree editor",kind:"web",color:"#d8dec8",accent:"#62743c",image:"family.svg",media:[{type:"image",src:"fam1.png",alt:"Family Tree main screen",poster:""},{type:"image",src:"fam2.png",alt:"Family Tree second screen",poster:""}],description:"An interactive family tree with a text editor. Explore relationships, edit the graph, and import or export your tree. No account required.",tags:["Interactive editor","Text import/export","No account"],note:"",links:[["Visit site","https://scout-38aa2.web.app/family/"]],private:!0}],T=[{id:"map",name:"Map",category:"Web · Routes & journey timing",description:"A map experiment for saved routes, journey timing, and comparing your movement with a virtual pace setter.",private:!0,missing:!1,hosted:!0,links:[["Visit site","https://scout-38aa2.web.app/map"]]},{id:"university-projects",name:"University projects",category:"Archive · CS coursework",description:"Computer vision, population simulation, timetable optimisation, 3D graphics, games, and more.",private:!1,missing:!1,hosted:!0,links:[["Explore archive","https://yissok.github.io/"]]},{id:"block-cipher-aes-128-apps",name:"Block Cipher AES-128 apps",category:"Swift · Encryption",description:"Client-side shortcuts that hook into the system to encrypt and decrypt text with AES-128.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/your-encrypter"]]},{id:"picture-encrypter",name:"Picture encrypter",category:"Swift · Image processing",description:"Turns pictures into noisy static artefacts with AES-128.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/encrypture"]]},{id:"kubernetes-full-stack",name:"Kubernetes full-stack",category:"React · Java · Kubernetes",description:"A template app with a Java backend and React frontend, accessed directly through the server IP.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/kube"]]},{id:"cost-saving-personal-backend",name:"Cost-saving personal backend",category:"AWS · Node · MongoDB",description:"API gateway backend with MongoDB and Node EC2 auth, CloudFront static hosting, and CloudFormation + GitHub Actions infrastructure.",private:!1,missing:!1,hosted:!0,links:[["Backend","https://github.com/yissok/backend"],["Static frontend","https://github.com/yissok/static-frontend"],["Node bastion","https://github.com/yissok/node-bastion"]]},{id:"serverless-chat",name:"Serverless Chat",category:"Swift · Peer-to-peer",description:"Throwaway Firebase key hardcoded in the app wraps a more precious APNS key for notifications — a free way to have a chat app without running a server.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/no-strings"]]},{id:"zero-operating-cost-contractor-site-tap-in",name:"Zero operating cost Contractor site tap in",category:"Google Apps Script",description:"A Google Sheets database with a static UI, running at zero operating cost.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/site"]]},{id:"coffee-chatbot",name:"Coffee chatbot",category:"Python",description:"A bot crowdsourcing coffee deliveries through Symphony chat APIs. Built, but not hosted anywhere and without a repository anymore.",private:!1,missing:!0,hosted:!0,links:[]},{id:"knowledge-share-chatbot",name:"Knowledge-share chatbot",category:"Node.js · MySQL",description:"A full-stack project that routes questions to the right people.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/nomuraLifehacks"]]},{id:"structured-notes",name:"Structured Notes",category:"Notes",description:"Notes taken via an iOS shortcut, keyed by their first word into a map, optionally encrypted locally, then persisted to a GitHub repo.",private:!0,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Structured-Notes"]]},{id:"peer-to-peer-chat",name:"Peer to Peer Chat",category:"P2P chat",description:"A browser chat experiment that sends messages to multiple peers over WebRTC, with a Node.js server helping establish connections.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Peer-to-Peer-Chat"]]},{id:"light-pong",name:"Light Pong",category:"Game",description:"Two-player Pong built with Arduino: a moving LED is the ball, buttons return it, and a servo and melodies track the score.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Light-Pong"]]},{id:"physics-playground",name:"Physics Playground",category:"Physics sandbox",description:"An interactive 2D physics sandbox built on dyn4j, where bodies fall, collide and stack as you experiment with forces and constraints.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Physics-Playground"]]},{id:"recursive-text-adventure",name:"Recursive Text Adventure",category:"Text game",description:"A terminal text adventure written in Haskell, passing the game state through recursive function calls as each command changes the world.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Recursive-Text-Adventure"]]},{id:"arduino-tic-tac-toe",name:"Arduino Tic Tac Toe",category:"Arduino · Game",description:"Two Arduinos talk to each other through LDS light pulses and LED receptors, so two players can play tic tac toe over light.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Arduino-Tic-Tac-Toe"]]},{id:"corner-detector",name:"Corner Detector",category:"Computer vision",description:"Python computer vision experiments covering image convolution, object recognition with scaled and rotated templates, and SIFT feature detection.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Corner-Detector"]]},{id:"3d-playground",name:"3D Playground",category:"3D graphics",description:"A C++ and OpenGL playground for loading 3D models, exploring them with a movable camera, and switching between vertices, edges and shaded faces.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/3D-Playground"]]},{id:"asp-timetabling",name:"Answer Set Programming for timetabling",category:"ASP · Timetabling",description:"Generates university timetables from room, lecturer and student constraints, ranks schedules by preferences, and displays the results in a Java GUI.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Answer-Set-Programming-for-timetabling"]]},{id:"dungeon-of-doom",name:"Dungeon Of Doom",category:"Game",description:"A networked multiplayer dungeon game where players and bots compete to collect gold and reach an exit, with support for custom maps.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Dungeon-Of-Doom"]]},{id:"population-behaviours",name:"Population Behaviours",category:"Simulation",description:"A NetLogo simulation exploring how cooperation evolves, with agents that cooperate or defect and form spatial patterns through their interactions.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Population-Behaviours"]]},{id:"intensity-template-matching",name:"Intensity Based Template Matching",category:"Computer vision",description:"Finds a template inside a larger image by sliding it across the image and scoring pixel-intensity matches, using Python, NumPy, SciPy and OpenCV.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Intensity-Based-Template-Matching"]]},{id:"snake",name:"Snake",category:"Game · 2010",description:"An early Pascal project: a small version of the classic Snake game.",private:!1,missing:!1,hosted:!0,links:[["View repository","https://github.com/yissok/Snake"]]},{id:"new-1ff6d9c7",name:"Image Classifier",category:"MATLAB · Computer vision",description:"Recognises six classes of binary shapes using boundary chain codes, Fourier features and Gaussian models, with confusion matrices to evaluate predictions.",private:!0,missing:!1,hosted:!1,links:[["View repository","https://github.com/yissok/machine-learning-classifier"]]}],P=[{id:"yahoo",employer:"Yahoo",role:"Software Engineer",period:"Nov 2020 – Apr 2026",metric:"750+ PRs across 60+ repositories",stack:"Java 17 · Spring Boot 3 · Hibernate/JPA · MySQL · Liquibase/Flyway · AWS Lambda/CloudFormation/S3/EMR/Glue/Redshift · Kafka · Docker/Rancher · Chef · JUnit · Cucumber · JaCoCo · GitHub Enterprise · Screwdriver CI/CD · GitHub Actions",areas:[{id:"creative-platform",title:"Creative Management Platform",lede:"Lead maintainer for ~3.5 years of an internal Java GWT platform used by ~100 people, then lead developer of its Spring Boot 3 / Java 17 successor.",body:"Designed and built the successor service: REST API, RSQL-filtered list endpoints, Hibernate/JPA persistence, AOP-based audit logging, Google Sheets service-account integration, OpenAPI documentation, and a full CI/CD pipeline.",tags:"Java · Spring Boot · Hibernate/JPA · RSQL",items:[{title:"AWS operations",text:"The API runs on ECS Fargate with Micrometer and Spring Boot Actuator metrics scraped by Prometheus, plus a custom analytics viewer for the business. CloudWatch alarms route to on-call via Opsgenie, and I found and cut over-provisioning from an auto-update bot that was driving cost up."}]},{id:"legacy-migration",title:"Legacy Platform Migration",lede:"Drove a multi-year migration away from the legacy RAS ad-serving stack.",body:"Coordinated breaking changes across application, database, ETL and Lambda repositories, including canvas, canvas-db, reporting-db, AWS Glue jobs, and AWS Lambda functions.",tags:"AWS Glue · AWS Lambda",items:[]},{id:"revenue-attribution",title:"Revenue Attribution",lede:"Designed and shipped a metadata-driven system that links advertising revenue back to the internal creative team that produced the originating asset.",body:"The DSP API was too slow to check metadata per request, so I moved attribution-data extraction to the DSP UI instead, deployed it, and let the revenue team query the resulting database directly.",tags:"Java · Metadata pipelines",items:[]},{id:"data-platform",title:"Data Platform & Infrastructure",lede:"Owned significant parts of the big-data pipeline.",body:"Amazon Redshift schemas and views, AWS Glue ETL, Kafka event collection, Amazon EMR job orchestration, and AWS Lambda monitoring. Built emr-retry-cron from scratch for EMR job orchestration and retry handling.",tags:"Redshift · Glue · Kafka · EMR · Lambda",items:[]},{id:"ad-ops-api",title:"Ad Operations API",lede:"From 2024, lead backend contact for projects across four squads building a company-wide ad-operations API.",body:"The API serves ~400 active users across all time zones, with roughly 250 PRs landed over ~18 months. Important areas:",tags:"Java · Spring Boot · Hibernate/JPA · MySQL",items:[{title:"Goals & validation",text:"Multiple-KPI line- and package-level goal validators, a traffic API, package download, and audit logging."},{title:"Target Completion Rate",text:"Implemented TCR targeting across the domain model, validators, audit log and import/export, behind a two-phase feature flag rollout."},{title:"ROAS goal type",text:"ROAS support for Audio and CTV, including rewriting reporting calculations so dynamic conversion is prioritised appropriately."},{title:"AdLearn2 enforcement migration",text:"Stricter POST/PUT validation, status reporting, and a migration cron job touching existing data and state."},{title:"RAG AI assistant integration",text:"OAuth and CKMS (Doc360) support for a third-party RAG assistant: authentication, secret rotation and key sanitisation."}]},{id:"ai-tooling",title:"AI Tooling",lede:'Built a Claude Code skill called "where is my Jira ticket" that resolves which ticket a change belongs to.',body:"",tags:"Claude Code · Jira API",items:[{title:"Environment awareness",text:"The skill reads the current deploy environment — branch and deploy status — then sends a sub-agent to query the Jira API so anything linked to the change resolves into its ticket state and location."}]}]},{id:"nomura",employer:"Nomura",role:"Platform Engineering",period:"",metric:"",stack:"",areas:[{id:"mobile-framework",title:"Mobile Development Framework",lede:"Built the shared framework and wizard that standardises how work-profile apps are created, so every app ships with the same security and branding defaults instead of bespoke setups.",body:"",tags:"Mobile · Platform Engineering",items:[{title:"Approvals in one place",text:"Security, branding and legal/engineering-management approvals are folded into a single, auditable flow on every new app."},{title:"Three flows to one",text:"Collapsed three divergent deployment flows into one documented path that every app uses, removing the guesswork from shipping."}]}]}],x=JSON.parse(`[{"id":"peer-to-peer-chat","name":"Peer to Peer Chat","repoUrl":"https://github.com/yissok/Peer-to-Peer-Chat","tagline":"A browser chat experiment that sends messages to multiple peers over WebRTC.","how":["A JavaScript chat experiment that lets several browser pages exchange text using <strong>WebRTC data channels</strong>. Each page displays its assigned ID, a list of peers and the messages it receives.","A small Node.js signalling server introduces the peers. When a page connects over WebSocket, the server assigns it a numeric ID and shares the peer list. It then forwards the connection offers, answers and network candidates that browsers need to establish a WebRTC connection.","Choosing <em>Send message to ALL</em> walks through the peer list, skipping the sender. The client opens a connection to each recipient in turn and sends the text through its data channel. Chat text travels between peers; the server handles the connection setup.","The project extends an example caller-and-callee implementation with peer IDs, peer discovery and sending to multiple recipients. The original demonstration uses several browser pages connected to a local signalling server."],"media":[{"type":"video","src":"demos/ptp.mp4","alt":"","poster":"demos/ptp.png","original":"https://yissok.github.io/HQ_videos/ptp.mp4"}],"smart":["The Node.js server uses the <code>ws</code> library and listens on port <code>8090</code>; the browser client connects to <code>ws://localhost:8090/</code>.","Signalling messages are JSON objects carrying offers, answers, ICE candidates or peer IDs. The server forwards connection messages to their destination and includes the sender’s ID.","Each connection uses <code>RTCPeerConnection</code> and a data channel named <code>communication</code>. The initiating peer creates the channel before generating its offer.","The client stores the peer list in <code>localStorage</code>. A recursive function visits each recipient and waits a fixed <code>100 ms</code> before sending, rather than waiting for the channel’s open event.","This is a prototype: the server has no disconnect cleanup, and the fixed send delay assumes that each connection becomes ready quickly enough."],"links":[]},{"id":"reacter","name":"Reacter","repoUrl":"https://github.com/yissok/iOS-Game","tagline":"A tap-based reaction game for iPhone and iPad, first released in 2015.","how":["Reacter is a native iOS game about <strong>reaction speed</strong>: tap each target as quickly and accurately as possible to improve your score.","First released on the App Store in 2015, it was built with the Xcode tools available at the time. Much of that tooling has since been deprecated; the codebase is now a record of an early iOS project."],"media":[{"type":"video","src":"demos/reacter.mp4","alt":"","poster":"demos/reacter.png","original":"https://yissok.github.io/HQ_videos/reacter.mp4"}],"smart":["Released on the App Store in 2015.","Built around a single screen and a tap-timing mechanic.","The source reflects the iOS tooling used at the time."],"links":[["App Store","https://apps.apple.com/gb/app/reacter/id993435226"]]},{"id":"light-pong","name":"Light Pong","repoUrl":"https://github.com/yissok/Light-Pong","tagline":"Two-player Pong on an Arduino, played with light and sound.","how":["This project recreates the classic <strong>Pong</strong> game using Arduino hardware. Six LEDs simulate a ball moving back and forth between two players, with each player controlling a button at their end of the game.","Players must press their button when the moving light reaches their side. A correctly timed press scores a point, while pressing at the wrong moment awards a point to the opponent.","The game provides several forms of feedback. A servo motor indicates which player is winning and by how much, while a piezo element plays different melodies when the game starts, ends, or when a player scores or misses.","Game speed can be adjusted with a potentiometer, changing the interval between LED transitions from roughly 150 ms at the slowest setting to 50 ms at the fastest. When the game ends, all LEDs illuminate, a melody plays, and the LEDs on the winner's side blink repeatedly."],"media":[{"type":"video","src":"demos/pong.mp4","alt":"","poster":"demos/pong.png","original":"https://yissok.github.io/HQ_videos/pong.mp4"},{"type":"image","src":"uploads/39cb0d02-a0e2-4b4e-8c19-c84e716f86f4-screenshot-2026-09-21-180853.png","alt":"","poster":""}],"smart":["Six LEDs are used to simulate the movement of the Pong ball and provide score-related visual feedback.","Each player has a button connected to an interrupt pin so button presses can be detected during gameplay.","A servo motor points across a scale from <code>-5</code> to <code>+5</code> to represent the current score advantage; reaching either limit represents an advantage of five or more points.","A potentiometer controls game speed by adjusting the delay between LED transitions from approximately 150 ms down to 50 ms.","A piezo element provides audio feedback for game start, game end, successful scores, and failed attempts.","Straws are positioned around the LEDs so that refraction spreads their light through the length of the cylinder while also helping conceal the wiring.","The end-of-game sequence combines all LEDs turning on, a melody, and repeated blinking on the winner's side."],"links":[]},{"id":"physics-playground","name":"Physics Playground","repoUrl":"https://github.com/yissok/Physics-Playground","tagline":"A sandbox for poking 2D physics.","how":["An interactive sandbox for <strong>2D rigid-body physics</strong>, built on William Bittle’s dyn4j engine.","Bodies fall, collide, stack and settle in real time. The playground gives you a place to experiment with forces and constraints and see how they behave."],"media":[{"type":"video","src":"demos/physics.mp4","alt":"","poster":"demos/physics.png","original":"https://yissok.github.io/HQ_videos/physics.mp4"}],"smart":["Uses dyn4j for collision detection and rigid-body simulation.","Experiments with shapes, joints and forces.","Packaged as an executable JAR."],"links":[]},{"id":"recursive-text-adventure","name":"Recursive Text Adventure","repoUrl":"https://github.com/yissok/Recursive-Text-Adventure","tagline":"A text adventure written in Haskell, where the whole game state is passed down through recursion.","how":["A terminal text adventure written in <strong>Haskell</strong>. Each command passes the game state through recursive calls, using pure functions to model changes rather than mutating a shared world object.","The game lives in a single file, <code>functionalGame.hs</code>. Compile it with GHC and play in the terminal."],"media":[{"type":"video","src":"demos/haskell.mp4","alt":"","poster":"demos/haskell.png","original":"https://yissok.github.io/HQ_videos/haskell.mp4"}],"smart":["Game state passes through recursive function calls.","Written as a single Haskell source file, compiled with GHC."],"links":[]},{"id":"gym-app","name":"Gym Crowdedness","repoUrl":"https://github.com/yissok/Gym-App","tagline":"Hardware that senses how crowded the gym is, and a backend that predicts when to go.","how":["Fit In was designed to improve the student gym experience by providing better information about <strong>how busy the gym is and when to visit</strong>. The project focused on overcrowding at the university gym after research with students and Sports Training Village staff identified occupancy information as a useful area to improve.","A hardware counter tracks people entering and leaving the gym. Two laser sensors determine a person's direction of travel so the count can be increased or decreased accordingly. The recorded occupancy data is uploaded to a server every five minutes and the count is reset at 3am each day.","The website displays the current number of people in the gym, historical occupancy charts, and predictions based on previous data. Users can create an account and add their timetable so the system can combine their free periods with gym occupancy information and suggest better times to visit.","An Android app provides easier mobile access to the system through a JavaScript-enabled <code>WebView</code> connected to the mobile website. Because the app loads the website directly, changes to the web application can be made without publishing a new APK."],"media":[{"type":"video","src":"demos/fitin.mp4","alt":"","poster":"demos/fitin.png","original":"https://yissok.github.io/HQ_videos/fitin.mp4"}],"smart":["Gym occupancy is measured using two laser sensors connected to Arduino hardware; the order in which the beams are broken determines whether someone is entering or leaving.","Occupancy data is uploaded to the server every five minutes, with the locally maintained count reset to zero at 3am.","The web application was built using <code>HTML</code>, <code>CSS</code>, <code>JavaScript</code>, and <code>PHP</code>.","Historical gym data is stored and used by the prediction system to identify patterns and extrapolate future occupancy.","The timetable feature combines gym data with individual user availability to provide more personalised guidance on when to visit.","The account system supports registration, login, password changes, and PHP sessions; client-side JavaScript validation is followed by server-side validation through PHP, with data sent using jQuery <code>AJAX</code>.","The Android application consists of a JavaScript-enabled <code>WebView</code> and requires an internet connection in the implemented version.","The prototype used two boards for the counting hardware; proposed future development included combining this into a single embedded system, reducing the enclosure size, adding permanent mounting and power, and improving connectivity."],"links":[]},{"id":"arduino-tic-tac-toe","name":"Arduino Tic Tac Toe","repoUrl":"https://github.com/yissok/Arduino-Tic-Tac-Toe","tagline":"Two microcontrollers play tic tac toe by flashing light messages at each other.","how":["This project explores whether two computers can exchange useful information without wires, Wi-Fi, Bluetooth, or another conventional communication standard. Two Arduino boards communicate using <strong>light</strong>, with an LED on each board transmitting information and a light-dependent resistor on the other receiving it.","The communication system is used to play a game of noughts and crosses between two computers. A player enters the number of the square they want to fill through the serial monitor. Their board is updated locally, and the selected square number is sent to the connected Arduino.","The Arduino converts the move into a custom binary-like representation and transmits it through a sequence of LED flashes. The receiving Arduino detects those flashes with its light resistor, reconstructs the encoded value, converts it back into the corresponding square number, and updates the second player's board.","The two programs alternate between transmitting and receiving because one player must make the first move. This allows the complete game state to be communicated using only changes in light."],"media":[{"type":"video","src":"demos/tictactoe.mp4","alt":"","poster":"demos/tictactoe.png","original":"https://yissok.github.io/HQ_videos/tictactoe.mp4"},{"type":"image","src":"uploads/f1f49c22-6923-4fa5-9936-4b1974a86a31-screenshot-2026-09-21-181105.png","alt":"","poster":""}],"smart":["Each board uses an <strong>LED for transmission</strong> and a light-dependent resistor for reception, with the LED positioned as close as possible to the other Arduino's sensor.","Board positions are numbered from 1 to 9, left to right and top to bottom, and encoded using a custom four-digit binary-like representation.","The encoding communicates the least significant digit first rather than using ordinary binary conversion.","A 100 ms initial flash tells the receiver that an encoded message is about to begin, and each subsequent encoded digit also occupies a 100 ms interval.","The light resistors were empirically tested to sample light at intervals slightly faster than 50 ms. The receiver reads a 50 ms window from the middle of each 100 ms transmission interval to reduce the chance of sampling during a transition.","A complete move can be transmitted and read in less than half a second.","During development, the two Arduino boards were placed inside a box with a lid so that testing could be performed without interference from changing external light conditions."],"links":[]},{"id":"corner-detector","name":"Corner Detector","repoUrl":"https://github.com/yissok/Corner-Detector","tagline":"Computer-vision corner detection and feature matching built from scratch.","how":["This project explores several <strong>computer vision</strong> techniques in Python, covering image convolution, object recognition through intensity-based template matching, and an implementation of the SIFT feature-detection pipeline. It uses OpenCV, NumPy and SciPy for image processing and mathematical operations.","A custom convolution function applies kernels to greyscale images while preserving their dimensions through padding. It was tested using Gaussian blur, sharpening, horizontal edge detection and identity kernels, with its output compared against SciPy's convolution implementation.","For object recognition, training images are converted into collections of templates at multiple scales and rotations. During testing, these templates are moved across an input image and assigned correlation scores. The strongest match for each class is retained, filtered using a threshold, and used to draw a rotated, scaled bounding box labelled with the detected class.","The project also implements key stages of <strong>SIFT</strong>. Difference-of-Gaussians pyramids are used to locate candidate interest points across multiple scales, low-contrast points and edges are filtered out, and the remaining keypoints are assigned magnitudes and orientations. Descriptors represent the neighbourhood around each keypoint using orientation histograms."],"media":[{"type":"video","src":"demos/corner.mp4","alt":"","poster":"demos/corner.png","original":"https://yissok.github.io/HQ_videos/corner.mp4"}],"smart":["The project was written in Python using <code>OpenCV</code>, <code>NumPy</code>, <code>SciPy</code> and <code>Matplotlib</code>. ","The custom convolution implementation pads the source image and explicitly flips the supplied kernel before applying it. Its results were checked against <code>scipy.ndimage.convolve</code>. ","Template matching operates on RGB data rather than greyscale so that colour information is preserved during matching. ","Training generates templates at four scales — 50%, 25%, 12.5% and 6.25% — and twelve rotations from 0° to 330° in 30° increments. ","Scaled and rotated templates are serialised into binary <code>.dat</code> files using Python's <code>pickle</code> library for faster loading during testing. ","Template matching uses OpenCV's <code>matchTemplate</code> with normalised correlation and applies an empirically selected threshold of <code>0.5</code> before drawing a detection.  ","The SIFT implementation uses three octaves, Difference of Gaussians for interest-point localisation, comparison against 26 neighbouring samples in space and scale, and Hessian-based filtering to reject edge responses. ","Each SIFT descriptor contains 16 orientation histograms with eight buckets each, producing 128 values per keypoint. "],"links":[]},{"id":"3d-playground","name":"3D Playground","repoUrl":"https://github.com/yissok/3D-Playground","tagline":"A raw OpenGL playground that loads and renders real 3D models.","how":["A C++ playground for experimenting with <strong>interactive 3D rendering</strong> using <code>OpenGL</code>.","It can load <code>.obj</code> meshes such as the Stanford bunny and a screwdriver, automatically scale and position them within the scene, and render them as <em>vertices</em>, <em>edges</em>, or shaded faces.","The scene can be explored using a mouse-controlled camera with movement relative to the viewing direction. An alternate grounded movement mode adds horizontal movement, gravity and jumping.","The renderer also supports lighting and materials, smooth shading using calculated vertex normals, and texture mapping for a cube using BMP textures."],"media":[{"type":"video","src":"demos/bunny.mp4","alt":"","poster":"demos/bunny.png","original":"https://yissok.github.io/HQ_videos/bunny.mp4"},{"type":"image","src":"uploads/2a92b3c4-c703-426e-b8ed-4f2ee0256bb1-screenshot-2026-09-21-181137.png","alt":"","poster":""}],"smart":["Parses <code>.obj</code> vertex and face data and records which faces are connected to each vertex.","Calculates face normals using <strong>cross products</strong> and derives angle-weighted vertex normals for smooth shading.","Uses model bounds to automatically scale and translate imported meshes into the scene.","Implements camera rotation using yaw and pitch, with <code>gluLookAt</code> used to position and orient the view.","Derives camera-relative movement directions using vector normalisation and cross products.","Supports separate <em>vertex</em>, <em>edge</em>, and <em>face</em> rendering modes.","Uses <code>OpenGL</code> lighting, material properties, depth testing, and smooth shading.","Implements BMP texture mapping and an alternate movement mode with gravity-based jumping."],"links":[]},{"id":"asp-timetabling","name":"Answer Set Programming for timetabling","repoUrl":"https://github.com/yissok/Answer-Set-Programming-for-timetabling","tagline":"Prolog plus Java: a constraint solver that generates optimal timetables from rules.","how":["This project uses <strong>Answer Set Programming</strong> to generate valid university timetables from information about students, units, lecturers, rooms, available time slots, preferences, and other commitments. The solver is run with <code>clingo</code>, which produces the possible schedules satisfying the encoded rules and constraints.","The timetable model separates the generation of possible lecture and student assignments from constraints that remove invalid combinations. Weak constraints are then used to express preferences and reorder valid answer sets according to their optimisation score.","Results can be viewed directly as <code>clingo</code> output or passed as JSON to a Java program, <code>ASPinterpreter.java</code>, which provides a GUI for navigating the generated timetable. The project also includes separate basic, extended, and edge-case test inputs.","Runtime testing investigated how different input sizes affect solving time. The largest increases came from the number of available time slots and the total number of lecture hours, because these substantially increase the number of possible arrangements that the solver must consider."],"media":[{"type":"video","src":"demos/asp.mp4","alt":"","poster":"demos/asp.png","original":"https://yissok.github.io/HQ_videos/asp.mp4"}],"smart":["The core timetable logic is implemented in <strong>Answer Set Programming</strong> and executed using <code>clingo</code>.","<code>.pl</code> was used as the extension for the ASP files to obtain syntax highlighting in the IDE.","A Java program, <code>ASPinterpreter.java</code>, consumes <code>clingo</code>'s JSON output using <code>json-simple-1.1.jar</code> and presents the results through a GUI.","The ASP model uses generators and constraints to construct valid answer sets, while weak constraints are used for optimisation and preference ordering.","The student-attendance generator includes <code>takes(S,U)</code> so that impossible student/unit combinations are excluded during generation rather than produced and filtered later.","The model includes support for grouping clusters of lecture preferences.","Tests were organised into <code>basic</code>, <code>ext</code>, and <code>edge</code> sets and were run with different input configurations to check correctness and investigate runtime behaviour.","Runtime experiments showed that the search space grows rapidly with the number of time slots and total lecture hours; for <code>n</code> available time slots and <code>k</code> lecture hours, the analysed arrangement count follows <code>n!/(n-k)!</code>."],"links":[]},{"id":"dungeon-of-doom","name":"Dungeon Of Doom","repoUrl":"https://github.com/yissok/Dungeon-Of-Doom","tagline":"A networked multiplayer dungeon game with a clickable map, a bot, and native-speed game logic.","how":["This project is a <strong>multiplayer dungeon game</strong> built around a client-server architecture. The server is started first and loads either the default map or a custom map composed from legal tiles representing floor, walls, gold, and exits.","Players connect through the <code>PlayGame</code> client and move around the map looking for gold before attempting to escape through an exit. The amount of gold required to leave the dungeon is defined in the map file, so different maps can impose different winning conditions.","Multiple players can connect to the same server and compete for the available gold. Players cannot occupy the same tile simultaneously, which makes movement and positioning part of the competition.","The game also supports bots launched through <code>BotLauncher</code>. Bots connect to the same map and follow the same movement rules as human players, allowing the game to be played without additional human clients."],"media":[{"type":"video","src":"demos/dod.mp4","alt":"","poster":"demos/dod.png","original":"https://yissok.github.io/HQ_videos/dod.mp4"}],"smart":["The project uses separate <code>Server</code>, <code>PlayGame</code>, and <code>BotLauncher</code> classes for hosting the game, connecting human players, and spawning bots.","Custom maps can be created by editing text files in the <code>maps</code> directory using the supported tile symbols <code>.</code>, <code>#</code>, <code>G</code>, and <code>E</code>.","The server retains the same communication protocol as the earlier text-based version of the project, except for changes to <code>LOOK</code> responses required to support multiple clients.","The GUI communicates with the server through the same underlying communication structure as the previous text UI.","Player movement is animated using a custom tile display made from small panels; each tile contains an 8×8 panel grid whose rows and columns are updated progressively to create the appearance of movement.","The GUI uses <code>GridBagLayout</code> and supports resizing.","The server has a maximum of 20 clients in the current implementation; disconnected clients are not dynamically replaced through a reusable client-slot mechanism.","The client provides a built-in quit action that disconnects gracefully from the server, while closing the GUI window remains a separate action."],"links":[]},{"id":"population-behaviours","name":"Population Behaviours","repoUrl":"https://github.com/yissok/Population-Behaviours","tagline":"Agent-based modelling of how cooperation survives in harsh environments.","how":["A NetLogo model exploring <strong>how cooperation evolves</strong>. Agents choose whether to cooperate or defect, following dynamics from studies by Smaldino, Schank and McElreath (2013), and Smaldino (2013).","Load the model in NetLogo Web to watch agents interact. Spatial patterns and the effects of cooperation costs emerge from their individual rules."],"media":[{"type":"video","src":"demos/swarm.mp4","alt":"","poster":"demos/swarm.png","original":"https://yissok.github.io/HQ_videos/swarm.mp4"}],"smart":["Based on published models of cooperation from 2013.","Agent rules produce spatial patterns during the simulation.","The model can be loaded in NetLogo Web."],"links":[]},{"id":"intensity-template-matching","name":"Intensity Based Template Matching","repoUrl":"https://github.com/yissok/Intensity-Based-Template-Matching","tagline":"Finds where a template appears in an image by comparing pixel intensity.","how":["A Python project that finds a template patch inside a larger image using <strong>pixel intensity</strong>. It slides the template across the target and scores how closely each position matches.","A main script runs the pipeline against test images, using SciPy, NumPy and OpenCV. The modules follow the same structure as the companion Corner Detector project."],"media":[{"type":"video","src":"demos/waldo.mp4","alt":"","poster":"demos/waldo.png","original":"https://yissok.github.io/HQ_videos/waldo.mp4"}],"smart":["A sliding window compares the template against positions in the image.","Configuration, convolution and matching live in separate modules.","Match scores are based on pixel intensity."],"links":[]},{"id":"snake","name":"Snake","repoUrl":"https://github.com/yissok/Snake","tagline":"An early Pascal project from 2010.","how":["I wrote this version of Snake in <strong>2010</strong>, using Pascal. It is a small early project: move around the grid, collect food and avoid the walls and your own tail.","The source is kept here as part of the archive of my earlier work. The game lives in a single file, <code>snake.pas</code>."],"media":[{"type":"video","src":"demos/snake.mp4","alt":"","poster":"demos/snake.png","original":"https://yissok.github.io/HQ_videos/snake.mp4"}],"smart":["Written in Pascal in 2010.","Input, movement, collision detection and drawing are in snake.pas."],"links":[]},{"id":"serverless-chat","name":"Serverless chat","repoUrl":"https://github.com/yissok/Serverless-Chat","tagline":"An experiment with peer-to-peer messaging and push notifications on iOS.","how":["A two-person iOS chat app built with Swift and <strong>peer-to-peer networking</strong>. Messages travel between devices rather than through a dedicated chat server.","The project also explores a Firebase and APNS setup for push notifications, using a disposable Firebase credential embedded in the app."],"media":[],"smart":["Messages use peer-to-peer transport.","The notification setup uses Firebase and APNS.","A disposable Firebase credential is embedded in the app."],"links":[["View repository","https://github.com/yissok/Serverless-Chat"]]},{"id":"structured-notes","name":"Structured notes","repoUrl":"https://github.com/yissok/Structured-Notes","tagline":"Notes taken through an iOS shortcut, keyed by their first word into a map, optionally encrypted, then persisted to a GitHub repo.","how":["An iOS Shortcut note-taking system that <strong>organises notes by their first word</strong>. For example, <em>groceries: milk</em> goes under groceries, while <em>idea: deck</em> goes under idea.","A second shortcut creates new keys. Notes under selected keys can be encrypted locally before another shortcut saves the map to a GitHub repository.","To read notes back, query the repository by keyword. Plaintext notes come from the map; encrypted notes are passed to the app through an app URL and opened there."],"media":[{"type":"video","src":"demos/snotes.mp4","alt":"","poster":"demos/snotes.png","original":"https://yissok.github.io/HQ_videos/snotes.mp4"}],"smart":["The first word of a note selects its key.","Shortcuts create keys and save the notes to a GitHub repository.","Selected notes are encrypted locally and opened through the app."],"links":[["View repository","https://github.com/yissok/Structured-Notes"]]},{"id":"latent-semantic-analysis","name":"Latent Semantic Analysis","repoUrl":"https://github.com/yissok/Blending-Google-and-the-old-Yahoo","tagline":"Estimates how strongly keywords relate by blending Google search signals with an old Yahoo directory.","how":["An experiment in <strong>keyword relatedness</strong>. Given a set of keywords, it estimates relationships between pairs and displays them as a weighted graph.","The score combines Google search signals with the older, human-curated Yahoo directory, bringing together two sources of evidence about how terms relate.","A PHP backend stores and computes counts, while a canvas interface renders the network."],"media":[{"type":"video","src":"demos/yoogle.mp4","alt":"","poster":"demos/yoogle.png","original":"https://yissok.github.io/HQ_videos/yoogle.mp4"}],"smart":["Combines search co-occurrence with Yahoo directory relationships.","Displays pairwise scores as a weighted graph.","The PHP backend stores counts for reuse."],"links":[]},{"id":"new-1ff6d9c7","name":"Image Classifier","repoUrl":"https://github.com/yissok/machine-learning-classifier","tagline":"A MATLAB classifier that recognises binary shapes from their boundaries.","how":["This MATLAB project implements an <strong>image classifier</strong> for six classes of binary shapes: Alien, Arrow, Butterfly, Face, Star and Toonhead. It extracts an object’s boundary, converts it into numerical features, and predicts which class the object belongs to.","The boundary is represented using a chain code that records movements along the edge between the black and white regions of the image. A Fourier transform is then applied to this boundary representation so that classification can focus on the object's overall shape rather than small details or artefacts. Only the first few low-frequency components are retained as the feature vector.","Training calculates the mean, covariance, and prior probability for each class from labelled images. During classification, a new feature vector is evaluated against these class distributions using a Gaussian-based probability score and assigned to the class with the strongest result.","Testing compares predicted classes with the classes encoded in the test-image filenames and records the results in a <strong>confusion matrix</strong>, making it possible to see both correct classifications and which classes are confused with one another.","The recovered project includes 222 training images, 221 test images, saved model workspaces and the original report. Its source is kept in a private repository."],"media":[{"type":"image","src":"uploads/0e43785c-833b-4792-8c7d-1786b326c775-screenshot-2026-09-21-181005.png","alt":"","poster":""},{"type":"image","src":"uploads/876b6c34-65ac-42b7-9913-0da54ede4459-screenshot-2026-09-21-181011.png","alt":"","poster":""}],"smart":["The input images are binary and were designed without holes or multiple internal boundaries because the chain-code implementation follows a single boundary. ","Boundary movements are converted into the frequency domain using a Fourier transform, with low frequencies retained to represent high-level shape while discarding finer detail. ","Experiments with feature-vector size found that using the first <strong>six Fourier features</strong> gave the best performance on the provided image set.  ","Training stores the mean and covariance calculated for each class in a <code>.mat</code> file and derives class priors from the number of training examples belonging to each class. ","Classification uses the class likelihood and prior probability in a Bayes-rule-based score; the common <code>p(x)</code> term is omitted because it is identical across the classes being compared. ","Logarithms are used in the probability calculation to reduce rounding problems when working with very small values. ","Testing produces a normalised confusion matrix so that misclassifications can be inspected by both actual and predicted class. ","<code>train(N)</code> builds class models using N Fourier features; <code>classify(imagepath)</code> loads the saved workspace and returns the highest-scoring class.","<code>testMultipleFrequencies.m</code> compares feature counts from 2 to 30 by retraining and evaluating the classifier at each setting.","The archived MATLAB code retains its original local paths. The repository README explains the path adjustments needed before running training and evaluation."],"links":[]},{"id":"new-5a52dd88","name":"New project","repoUrl":"","tagline":"","how":[],"media":[],"smart":[],"links":[]},{"id":"penguin-steps","name":"Penguin Steps","repoUrl":"","tagline":"Compare your daily steps with a partner through Apple Health. Your penguins move as you walk, turning the day into a shared race.","how":["Penguin Steps turns daily walking into a <strong>shared race with a partner</strong>. Pair up in the iOS app and compare your daily step totals through two penguins that move as you walk.","Step tracking uses Apple Health, so the race is driven by your recorded activity. The app brings the comparison into one place instead of requiring you to exchange step counts manually.","The native app is written in Swift and uses Firebase. Pairing and step tracking take place in the iOS app."],"media":[{"type":"image","src":"penguin-steps-screen.jpg","alt":"Penguin Steps main screen","poster":""},{"type":"image","src":"penguinsteps2.jpg","alt":"Penguin Steps second screen","poster":""}],"smart":[],"links":[["App Store","https://apps.apple.com/gb/app/penguin-steps/id6762652426"]]},{"id":"dropleet","name":"Dropleet","repoUrl":"","tagline":"Breaks LeetCode problems into bite-sized reasoning steps you can work through interactively. Question sets are LLM-generated from user-supplied JSON, answers flow through Google Forms, and the whole thing runs as a static site you can share — no account or backend required.","how":["Dropleet breaks <strong>Java interview problems</strong> into smaller reasoning steps. Work through a sequence of interactive questions to practise the decisions behind a solution.","Question sets are generated by an LLM from user-supplied JSON. The resulting practice material is published as a static website that can be shared with other learners.","Answers are submitted through Google Forms. This lets the site collect responses without running its own application backend or requiring a Dropleet account."],"media":[{"type":"image","src":"dropleet.jpg","alt":"Dropleet main screen","poster":""},{"type":"image","src":"drop2.png","alt":"Dropleet second screen","poster":""},{"type":"image","src":"drop3.png","alt":"Dropleet third screen","poster":""}],"smart":[],"links":[["Visit site","https://dropleet.co.uk/"]]},{"id":"pixelbot","name":"Pixelbot","repoUrl":"","tagline":"Watch a pixel on your Mac and get a notification on your phone when it changes — useful for queues, long operations and finished downloads.","how":["Pixelbot watches a <strong>pixel on your Mac</strong> and sends a notification to your phone when it changes. A small visual change can tell you that a queue has moved, a download has finished or a long operation has completed.","The two apps have separate roles: Pixelbot Dashboard on macOS monitors the selected pixel, while Pixelbot on iOS delivers the notification. You can leave the computer and still hear when the screen changes.","The workflow does not require an account. Both the Mac dashboard and the iOS companion are available through their respective App Stores."],"media":[{"type":"video","src":"pixelbot-video.mp4","alt":"Pixelbot demo","poster":""},{"type":"image","src":"pixelbot-screen.jpg","alt":"Pixelbot iPhone app","poster":""},{"type":"image","src":"pixelbot-dashboard-screen.jpg","alt":"Pixelbot Mac dashboard","poster":""}],"smart":[],"links":[["App Store","https://apps.apple.com/gb/app/pixelbot/id1560553386"],["Mac App Store","https://apps.apple.com/gb/app/pixelbot-dashboard/id1560523831?mt=12"]]},{"id":"cell","name":"Cell Counter","repoUrl":"","tagline":"Counts the cells visible in a photo of a microscope screen, plus tools for seeding density, well counts and media volumes. No account required.","how":["Cell Counter estimates the number of cells visible in a <strong>photo of a microscope screen</strong>. It uses image processing to turn the picture into a count.","The site also brings together calculations for seeding density, well counts and media volumes, so counting and preparation can be handled in the same tool.","It runs as a web application and does not require an account. The screenshots below show the counting interface and supporting calculators."],"media":[{"type":"image","src":"cell1.png","alt":"Cell Counter main screen","poster":""},{"type":"image","src":"cell2.png","alt":"Cell Counter second screen","poster":""},{"type":"image","src":"cell3.png","alt":"Cell Counter third screen","poster":""},{"type":"image","src":"cell4.png","alt":"Cell Counter fourth screen","poster":""}],"smart":[],"links":[["Visit site","https://scout-38aa2.web.app/cell"]]},{"id":"family","name":"Family Tree","repoUrl":"","tagline":"An interactive family tree with a text editor. Explore relationships, edit the graph, and import or export your tree. No account required.","how":["Family Tree combines an <strong>interactive relationship graph</strong> with a text editor. You can explore connections between family members and edit the tree.","Text import and export let you move a tree into or out of the editor. This provides a way to keep a copy of the relationship data as well as exploring it visually.","The editor is available in the browser and does not require an account."],"media":[{"type":"image","src":"fam1.png","alt":"Family Tree main screen","poster":""},{"type":"image","src":"fam2.png","alt":"Family Tree second screen","poster":""}],"smart":[],"links":[["Visit site","https://scout-38aa2.web.app/family/"]]},{"id":"map","name":"Map","repoUrl":"","tagline":"A map experiment for saved routes, journey timing, and comparing your movement with a virtual pace setter.","how":["A map experiment for exploring <strong>routes, journey timing and pace</strong>. Saved routes provide a path to follow, while movement and timing help describe progress along the journey.","A virtual pace setter gives you a moving reference to compare with your own position. The project brings together route planning and a visual way to understand how quickly you are travelling."],"media":[],"smart":[],"links":[["Visit site","https://scout-38aa2.web.app/map"]]},{"id":"block-cipher-aes-128-apps","name":"Block Cipher AES-128 apps","repoUrl":"https://github.com/yissok/your-encrypter","tagline":"Client-side shortcuts that hook into the system to encrypt and decrypt text with AES-128.","how":["A Swift project for <strong>encrypting and decrypting text with AES-128</strong>. Client-side shortcuts connect the encryption tools to system workflows.","The workflow takes text through an encryption or decryption action on the device. System integration makes those actions accessible as shortcuts rather than requiring a separate hosted service."],"media":[],"smart":[],"links":[]},{"id":"picture-encrypter","name":"Picture encrypter","repoUrl":"https://github.com/yissok/encrypture","tagline":"Turns pictures into noisy static artefacts with AES-128.","how":["Picture encrypter applies <strong>AES-128 to pictures</strong>, turning their contents into images that look like noisy static.","The project combines Swift, image processing and encryption to explore how picture data can be transformed into a visually scrambled result. Its source repository is private."],"media":[],"smart":[],"links":[]},{"id":"kubernetes-full-stack","name":"Kubernetes full-stack","repoUrl":"https://github.com/yissok/kube","tagline":"A template app with a Java backend and React frontend, accessed directly through the server IP.","how":["A template application combining a <strong>React frontend and Java backend</strong> in a Kubernetes setup.","The frontend provides the browser interface and the Java service supplies the backend. The application is accessed through the server IP, providing a starting point for experimenting with a full-stack deployment."],"media":[],"smart":[],"links":[]},{"id":"cost-saving-personal-backend","name":"Cost-saving personal backend","repoUrl":"https://github.com/yissok/backend","tagline":"API gateway backend with MongoDB and Node EC2 auth, CloudFront static hosting, and CloudFormation + GitHub Actions infrastructure.","how":["An AWS infrastructure experiment for hosting a <strong>personal application backend</strong>. It combines an API Gateway setup with a Java backend and a Node.js authentication service on EC2, using MongoDB for storage.","The static frontend is served through CloudFront. Keeping the static website separate from the backend allows the interface and server components to be managed independently.","CloudFormation describes the infrastructure, while GitHub Actions handles build and deployment steps. The work is split across backend, static-frontend and node-bastion repositories."],"media":[],"smart":[],"links":[["Static frontend","https://github.com/yissok/static-frontend"],["Node bastion","https://github.com/yissok/node-bastion"]]},{"id":"zero-operating-cost-contractor-site-tap-in","name":"Zero operating cost Contractor site tap in","repoUrl":"https://github.com/yissok/site","tagline":"A Google Sheets database with a static UI, running at zero operating cost.","how":["A contractor site tap-in project built around a <strong>Google Sheets database</strong> and a static user interface.","Google Apps Script connects the interface to the spreadsheet. The design uses those existing services to support the workflow without operating a dedicated application server."],"media":[],"smart":[],"links":[]},{"id":"coffee-chatbot","name":"Coffee chatbot","repoUrl":"","tagline":"A bot crowdsourcing coffee deliveries through Symphony chat APIs. Built, but not hosted anywhere and without a repository anymore.","how":["A Python chatbot for <strong>crowdsourcing coffee deliveries</strong> through Symphony chat APIs.","The project brought coffee requests into a chat workflow, using a bot to help coordinate deliveries. It was built, but is no longer available as a hosted application.","Built during a hackathon at Nomura, the project won <strong>first place out of 10 teams</strong>."],"media":[],"smart":[],"links":[],"availability":"This project was built during a hackathon at Nomura on internal company laptops, so the source code is not available here. The bot is not hosted publicly; this page preserves a description of what it did."},{"id":"knowledge-share-chatbot","name":"Knowledge-share chatbot","repoUrl":"https://github.com/yissok/nomuraLifehacks","tagline":"A full-stack project that routes questions to the right people.","how":["A chatbot that helps <strong>route questions to the right people</strong>. The idea is to make knowledge within a group easier to find by connecting a question with someone who can help.","The full-stack project uses Node.js and MySQL. Its source repository is private."],"media":[],"smart":[],"links":[]}]`),I={version:k,site:A,featuredProjects:S,archiveProjects:T,work:P,projectDetails:x};export{I as c,j as i};
